// Fork of "Fractal Basic 1" by soundmasteraj. https://shadertoy.com/view/X3dyRf
// 2024-12-29 20:12:08

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 normalizedCoord = fragCoord/iResolution.xy *2.0 - 1.0;

    float val = 0.2;
    val += sin(iTime)*.05;

    // float iterVal = 16. + abs(sin(iFrame)*16.));

    for (float i = 0.0; i < 32.0; i += 1.0){

    normalizedCoord = abs(normalizedCoord)+dot(normalizedCoord, normalizedCoord)*.08;
    normalizedCoord -= .5 + abs(sin(iTime)*0.25);
    normalizedCoord *= 1.21 - abs(sin(iTime)*.05);
    mat2 thing = mat2(
        cos(val), -sin(val),
        sin(val), cos(val)
    );

    thing *=     mat2(
        cos(-val-.1), -sin(val-.1),
        sin(val-.1), cos(-val-.1)
    );

    normalizedCoord *= thing*.95;

    };


    // Output to screen
    fragColor = vec4(vec3(length(normalizedCoord)), 1.0);
}
